Here's a simple function that sorts a JSON object by its keys:

```javascript
function sortJSONByKeys(json) {
  const sortedKeys = Object.keys(json).sort();
  const sortedObject = {};

  sortedKeys.forEach((key) => {
    sortedObject[key] = json[key];
  });

  return sortedObject;
}
```

You can use this function like this:

```javascript
const json = {
  apple: 1,
  banana: 2,
  cherry: 3,
};

const sortedJson = sortJSONByKeys(json);
console.log(sortedJson); // Output: {"apple": 1, "banana": 2, "cherry": 3}
```

