```cpp
#include <iostream>
#include <string>
#include <sstream>
#include <stdexcept>

using namespace std;

int fibonacci(int n, int a, int b) {
    if (n == 0) {
        return a;
    } else {
        return fibonacci(n - 1, b, a + b);
    }
}

int main() {
    string input;
    int first_num, second_num, num_elements;

    cout << "Enter the first two integers: ";
    getline(cin, input);

    istringstream iss(input);
    iss >> first_num >> second_num;

    if (iss.fail()) {
        throw runtime_error("Invalid input");
    }

    if (first_num < 0 || second_num < 0) {
        throw runtime_error("Both numbers must be non-negative");
    }

    cout << "Enter the number of sequence elements to generate: ";
    cin >> num_elements;

    if (num_elements <= 0) {
        throw runtime_error("Number of elements must be positive");
    }

    int sequence[num_elements];
    sequence[0] = first_num;
    sequence[1] = second_num;

    for (int i = 2; i < num_elements; i++) {
        sequence[i] = fibonacci(i, sequence[i - 2], sequence[i - 1]);
    }

    cout << "Fibonacci sequence: ";
    for (int i = 0; i < num_elements; i++) {
        cout << sequence[i] << ", ";
    }
    cout << endl;

    return 0;
}
```

